using System;using System.Collections.Generic;public class Solution{int Hist(int[]h){var st=new Stack<int>();int b=0;for(int i=0;i<=h.Length;i++){int cur=i==h.Length?0:h[i];while(st.Count>0&&h[st.Peek()]>cur){int ht=h[st.Pop()],l=st.Count==0?-1:st.Peek();b=Math.Max(b,ht*(i-l-1));}st.Push(i);}return b;}public int MaximalRectangle(char[][]m){if(m.Length==0)return 0;int[]h=new int[m[0].Length];int b=0;foreach(var r in m){for(int j=0;j<r.Length;j++)h[j]=r[j]=='1'?h[j]+1:0;b=Math.Max(b,Hist(h));}return b;}}
